import React, { Component } from 'react';
import {
    CButton, CCard, CCardBody, CCol, CContainer, CRow,
} from '@coreui/react';
import { requestHeaderGETWithAuth } from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { Logger, reloadPage } from '../../Utils/Utils';
import { Loading } from '../Statuses/Statuses';
import { BACKEND_NEXUS_APP_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';
import FailureModal from '../Modals/FailureModal';

const FILE_NAME = "MediaDataSlideshow.js";

const API_BASE = BACKEND_NEXUS_APP_BASE_URL + '/v1/media-data';

// Milliseconds each image is shown before auto-advancing (videos advance when they end).
const AUTOPLAY_INTERVAL_MS = 4000;

// The manifest's streamUrl is host-relative (e.g. "/nexus/v1/media-data/1/file?name=x.jpg").
// Prefix it with the backend origin so <img>/<video> load from the API host, not the SPA host.
const backendOrigin = () => {
    try {
        return new URL(BACKEND_NEXUS_APP_BASE_URL).origin;
    } catch (e) {
        return '';
    }
};

class MediaDataSlideshow extends Component {

    constructor(props) {
        super(props);
        this.state = {
            isLoaded: false,
            failureModalVisible: false,
            manifest: null,
            currentIndex: 0,
            playing: false,
            isFullscreen: false,
            // image zoom/pan: zoom is a scale factor (1 = fit), pan is the translate offset in px
            zoom: 1,
            panX: 0,
            panY: 0,
        };
        this.autoplayTimer = null;
        this.stageRef = React.createRef();
        // drag-to-pan tracking (only active while zoomed in)
        this.isPanning = false;
        this.panStart = { x: 0, y: 0, panX: 0, panY: 0 };
    }

    getMediaId() {
        return this.props.match.params.id;
    }

    componentDidMount() {
        document.title = "Media Slideshow";
        this.fetchManifest();
        window.addEventListener('keydown', this.handleKeyDown);
        document.addEventListener('fullscreenchange', this.handleFullscreenChange);
        document.addEventListener('webkitfullscreenchange', this.handleFullscreenChange);
    }

    componentWillUnmount() {
        window.removeEventListener('keydown', this.handleKeyDown);
        document.removeEventListener('fullscreenchange', this.handleFullscreenChange);
        document.removeEventListener('webkitfullscreenchange', this.handleFullscreenChange);
        // tear down any in-flight drag-to-pan listeners
        window.removeEventListener('mousemove', this.handlePanMove);
        window.removeEventListener('mouseup', this.handlePanEnd);
        this.clearAutoplay();
    }

    // ---------- data ----------

    fetchManifest = () => {
        const id = this.getMediaId();
        const url = API_BASE + '/' + id + '/slideshow';
        const userData = getUserDataFromLocalStorage();

        Logger(FILE_NAME, "fetchManifest", "REQUEST", "id", id);
        this.setState({ isLoaded: false });

        fetch(url, requestHeaderGETWithAuth(userData ? userData.authToken : null))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) {
                this.setState({ failureModalVisible: true });
                setTimeout(() => { logoutProcedureForLocalStorage(); reloadPage(); }, 500);
            }
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "fetchManifest", "RESULT", "result", result);
            const manifest = (result && result.data) || null;
            this.setState({ isLoaded: true, manifest, currentIndex: 0 }, this.scheduleAutoplay);
        })
        .catch(error => {
            Logger(FILE_NAME, "fetchManifest", "ERROR", "error", error);
            this.setState({ isLoaded: true, failureModalVisible: true });
        });
    }

    // ---------- helpers ----------

    items = () => (this.state.manifest && this.state.manifest.items) || [];

    currentItem = () => this.items()[this.state.currentIndex] || null;

    // Absolute URL for streaming an item's bytes.
    streamSrc = (item) => (item ? backendOrigin() + item.streamUrl : '');

    // ---------- navigation ----------

    goTo = (index) => {
        const total = this.items().length;
        if (total === 0) return;
        // wrap around for a continuous slideshow
        const next = ((index % total) + total) % total;
        // reset any image zoom/pan when moving to a different slide
        this.setState({ currentIndex: next, zoom: 1, panX: 0, panY: 0 }, this.scheduleAutoplay);
    }

    next = () => this.goTo(this.state.currentIndex + 1);

    prev = () => this.goTo(this.state.currentIndex - 1);

    handleKeyDown = (event) => {
        const isImage = this.currentItem() && this.currentItem().type === 'IMAGE';
        if (event.key === 'ArrowRight') this.next();
        else if (event.key === 'ArrowLeft') this.prev();
        else if (event.key === ' ') { event.preventDefault(); this.togglePlaying(); }
        else if (event.key === 'f' || event.key === 'F') this.toggleFullscreen();
        // image zoom shortcuts: + / = to zoom in, - to zoom out, 0 to reset
        else if (isImage && (event.key === '+' || event.key === '=')) { event.preventDefault(); this.zoomIn(); }
        else if (isImage && event.key === '-') { event.preventDefault(); this.zoomOut(); }
        else if (isImage && event.key === '0') { event.preventDefault(); this.resetZoom(); }
    }

    // ---------- fullscreen ----------

    // Keep React state in sync with the actual fullscreen element. This also handles the
    // user pressing Esc, which exits fullscreen without going through toggleFullscreen.
    handleFullscreenChange = () => {
        const fsElement = document.fullscreenElement || document.webkitFullscreenElement;
        this.setState({ isFullscreen: !!fsElement });
    }

    toggleFullscreen = () => {
        const fsElement = document.fullscreenElement || document.webkitFullscreenElement;
        if (fsElement) {
            const exit = document.exitFullscreen || document.webkitExitFullscreen;
            if (exit) exit.call(document);
            return;
        }
        const node = this.stageRef.current;
        if (!node) return;
        const request = node.requestFullscreen || node.webkitRequestFullscreen;
        if (request) request.call(node);
    }

    // ---------- autoplay ----------

    clearAutoplay = () => {
        if (this.autoplayTimer) {
            clearTimeout(this.autoplayTimer);
            this.autoplayTimer = null;
        }
    }

    // Advance images on a timer. Videos are left to advance on their `onEnded` event so we
    // don't cut a clip short.
    scheduleAutoplay = () => {
        this.clearAutoplay();
        if (!this.state.playing) return;
        const item = this.currentItem();
        if (!item) return;
        if (item.type === 'IMAGE' || item.type === 'OTHER') {
            this.autoplayTimer = setTimeout(this.next, AUTOPLAY_INTERVAL_MS);
        }
    }

    togglePlaying = () => {
        this.setState(prev => ({ playing: !prev.playing }), this.scheduleAutoplay);
    }

    onVideoEnded = () => {
        if (this.state.playing) this.next();
    }

    // ---------- image zoom / pan ----------

    MIN_ZOOM = 1;
    MAX_ZOOM = 8;
    ZOOM_STEP = 0.25;

    clampZoom = (z) => Math.min(this.MAX_ZOOM, Math.max(this.MIN_ZOOM, z));

    // Apply a new zoom level. When zooming back to (or below) 1 the pan offset is reset so the
    // image re-centers; pausing autoplay while the user is inspecting an image avoids it sliding away.
    setZoom = (nextZoomRaw) => {
        const nextZoom = this.clampZoom(nextZoomRaw);
        this.setState(prev => {
            const atBase = nextZoom <= this.MIN_ZOOM;
            return {
                zoom: nextZoom,
                panX: atBase ? 0 : prev.panX,
                panY: atBase ? 0 : prev.panY,
            };
        });
    }

    zoomIn = () => { this.clearAutoplay(); this.setZoom(this.state.zoom + this.ZOOM_STEP); }

    zoomOut = () => this.setZoom(this.state.zoom - this.ZOOM_STEP);

    resetZoom = () => this.setState({ zoom: this.MIN_ZOOM, panX: 0, panY: 0 });

    // Scroll-wheel zoom over the image. Wheel up zooms in, wheel down zooms out.
    handleImageWheel = (event) => {
        event.preventDefault();
        this.clearAutoplay();
        const delta = event.deltaY < 0 ? this.ZOOM_STEP : -this.ZOOM_STEP;
        this.setZoom(this.state.zoom + delta);
    }

    // Begin drag-to-pan (only meaningful when zoomed in beyond fit).
    handlePanStart = (event) => {
        if (this.state.zoom <= this.MIN_ZOOM) return;
        event.preventDefault();
        this.isPanning = true;
        this.panStart = { x: event.clientX, y: event.clientY, panX: this.state.panX, panY: this.state.panY };
        window.addEventListener('mousemove', this.handlePanMove);
        window.addEventListener('mouseup', this.handlePanEnd);
    }

    handlePanMove = (event) => {
        if (!this.isPanning) return;
        const dx = event.clientX - this.panStart.x;
        const dy = event.clientY - this.panStart.y;
        this.setState({ panX: this.panStart.panX + dx, panY: this.panStart.panY + dy });
    }

    handlePanEnd = () => {
        this.isPanning = false;
        window.removeEventListener('mousemove', this.handlePanMove);
        window.removeEventListener('mouseup', this.handlePanEnd);
    }

    // ---------- render ----------

    renderStage = (item) => {
        if (!item) {
            return <div style={{ color: '#bbb', padding: '80px 0' }}>No renderable content for this media record.</div>;
        }

        const src = this.streamSrc(item);
        const commonStyle = {
            // In fullscreen, fill the stage area (which flexes to take all space left after
            // the controls/thumbnails). Outside fullscreen, cap it inside the card.
            maxWidth: '100%',
            maxHeight: this.state.isFullscreen ? '100%' : '70vh',
            width: this.state.isFullscreen ? '100%' : undefined,
            height: this.state.isFullscreen ? '100%' : undefined,
            objectFit: 'contain',
            borderRadius: this.state.isFullscreen ? '0' : '6px',
            boxShadow: this.state.isFullscreen ? 'none' : '0 2px 12px rgba(0,0,0,0.35)',
        };

        if (item.type === 'VIDEO') {
            return (
                <video
                    key={src}
                    src={src}
                    style={commonStyle}
                    controls
                    autoPlay={this.state.playing}
                    onEnded={this.onVideoEnded}
                />
            );
        }

        if (item.type === 'IMAGE') {
            const { zoom, panX, panY } = this.state;
            const zoomed = zoom > this.MIN_ZOOM;
            const imageStyle = {
                ...commonStyle,
                transform: `translate(${panX}px, ${panY}px) scale(${zoom})`,
                // keep the image anchored to its center as it scales
                transformOrigin: 'center center',
                // no transition while actively panning, a gentle one for zoom button/wheel steps
                transition: this.isPanning ? 'none' : 'transform 0.12s ease-out',
                cursor: zoomed ? (this.isPanning ? 'grabbing' : 'grab') : 'zoom-in',
                // let us capture wheel/drag without the browser hijacking them
                touchAction: 'none',
                userSelect: 'none',
            };
            return (
                <img
                    key={src}
                    src={src}
                    alt={item.fileName}
                    style={imageStyle}
                    draggable={false}
                    onWheel={this.handleImageWheel}
                    onMouseDown={this.handlePanStart}
                    onDoubleClick={zoomed ? this.resetZoom : this.zoomIn}
                />
            );
        }

        // OTHER — offer a direct download / open link.
        return (
            <div style={{ padding: '40px 0' }}>
                <p style={{ color: '#ccc' }}>Preview not available for <strong>{item.fileName}</strong> ({item.contentType}).</p>
                <a href={src} target="_blank" rel="noopener noreferrer">Open / download file →</a>
            </div>
        );
    }

    renderThumbnails = () => {
        const items = this.items();
        if (items.length <= 1) return null;

        return (
            <div style={{ display: 'flex', gap: '8px', overflowX: 'auto', padding: '12px 4px', justifyContent: 'center', flexWrap: 'wrap' }}>
                {items.map((item, index) => {
                    const isActive = index === this.state.currentIndex;
                    const thumbStyle = {
                        width: '72px',
                        height: '72px',
                        objectFit: 'cover',
                        borderRadius: '4px',
                        cursor: 'pointer',
                        border: isActive ? '3px solid #321fdb' : '3px solid transparent',
                        opacity: isActive ? 1 : 0.7,
                    };
                    const src = this.streamSrc(item);
                    return item.type === 'IMAGE'
                        ? <img key={index} src={src} alt={item.fileName} title={item.fileName} style={thumbStyle} onClick={() => this.goTo(index)} />
                        : (
                            <div
                                key={index}
                                title={item.fileName}
                                style={{ ...thumbStyle, display: 'flex', alignItems: 'center', justifyContent: 'center', background: '#222', color: '#fff', fontSize: '24px' }}
                                onClick={() => this.goTo(index)}
                            >
                                {item.type === 'VIDEO' ? '🎞️' : '📄'}
                            </div>
                        );
                })}
            </div>
        );
    }

    renderHeader = () => {
        const m = this.state.manifest;
        if (!m) return null;
        return (
            <CCard className="mb-3">
                <CCardBody>
                    <CRow className="align-items-center">
                        <CCol md="9">
                            <h4 style={{ marginBottom: '6px' }}>
                                🎬 Media #{m.mediaDataId} {m.folder ? '(album)' : '(single file)'}
                            </h4>
                            <div style={{ color: '#666', wordBreak: 'break-all' }}>
                                <strong>File:</strong> {m.fileName || '—'}
                                {m.creator ? <> &nbsp;|&nbsp; <strong>Creator:</strong> {m.creator}</> : null}
                                {m.rating != null ? <> &nbsp;|&nbsp; <strong>Rating:</strong> {m.rating}</> : null}
                            </div>
                            {m.link && (
                                <div style={{ marginTop: '4px' }}>
                                    <a href={m.link} target="_blank" rel="noopener noreferrer">Source link →</a>
                                </div>
                            )}
                        </CCol>
                        <CCol md="3" className="text-right">
                            <CButton color="secondary" onClick={() => this.props.history.goBack()}>← Back</CButton>
                        </CCol>
                    </CRow>
                </CCardBody>
            </CCard>
        );
    }

    render() {
        Logger(FILE_NAME, "render", "", "currentIndex", this.state.currentIndex);

        if (!this.state.isLoaded) return <Loading />;

        const items = this.items();
        const item = this.currentItem();
        const hasItems = items.length > 0;

        return (
            <div>
                {this.renderHeader()}

                <CContainer>
                    <CCard>
                        {/* The fullscreen target wraps the stage + controls + thumbnails so
                            navigation stays usable while fullscreen. */}
                        <div
                            ref={this.stageRef}
                            style={{
                                background: '#1a1a1a',
                                padding: this.state.isFullscreen ? '16px' : '20px',
                                display: this.state.isFullscreen ? 'flex' : undefined,
                                flexDirection: this.state.isFullscreen ? 'column' : undefined,
                                justifyContent: this.state.isFullscreen ? 'center' : undefined,
                                height: this.state.isFullscreen ? '100vh' : undefined,
                                overflow: this.state.isFullscreen ? 'hidden' : undefined,
                            }}
                        >
                            {/* Stage */}
                            <div
                                style={{
                                    textAlign: 'center',
                                    minHeight: this.state.isFullscreen ? 0 : '40vh',
                                    flex: this.state.isFullscreen ? '1 1 auto' : undefined,
                                    display: 'flex',
                                    alignItems: 'center',
                                    justifyContent: 'center',
                                    background: '#1a1a1a',
                                    overflow: 'hidden',
                                }}
                            >
                                {this.renderStage(item)}
                            </div>

                            {/* Controls */}
                            {hasItems && (
                                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '16px', marginTop: '16px', color: '#eee' }}>
                                    <CButton color="light" onClick={this.prev} disabled={items.length <= 1}>⏮️ Prev</CButton>
                                    <CButton color={this.state.playing ? 'warning' : 'success'} onClick={this.togglePlaying}>
                                        {this.state.playing ? '⏸️ Pause' : '▶️ Play'}
                                    </CButton>
                                    <CButton color="light" onClick={this.next} disabled={items.length <= 1}>Next ⏭️</CButton>
                                    <CButton color="info" onClick={this.toggleFullscreen}>
                                        {this.state.isFullscreen ? '🡼 Exit Fullscreen' : '⛶ Fullscreen'}
                                    </CButton>
                                    {item && item.type === 'IMAGE' && (
                                        <span style={{ display: 'inline-flex', alignItems: 'center', gap: '6px' }}>
                                            <CButton color="light" onClick={this.zoomOut} disabled={this.state.zoom <= this.MIN_ZOOM} title="Zoom out">➖</CButton>
                                            <CButton color="light" onClick={this.zoomIn} disabled={this.state.zoom >= this.MAX_ZOOM} title="Zoom in">🔍➕</CButton>
                                            <CButton color="light" onClick={this.resetZoom} disabled={this.state.zoom === this.MIN_ZOOM} title="Reset zoom">⟲ {Math.round(this.state.zoom * 100)}%</CButton>
                                        </span>
                                    )}
                                    <span style={{ minWidth: '120px', textAlign: 'center' }}>
                                        {this.state.currentIndex + 1} / {items.length}
                                        {item ? <> &nbsp;·&nbsp; {item.type}</> : null}
                                    </span>
                                </div>
                            )}

                            {/* Thumbnails */}
                            {this.renderThumbnails()}
                        </div>
                    </CCard>
                </CContainer>

                <FailureModal visible={this.state.failureModalVisible} />
            </div>
        );
    }
}

export default MediaDataSlideshow;
